import{_ as r,a0 as l,w as s,s as d,ao as a,I as n,x as e,a1 as u,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在Ubuntu 13.10中升級GNOME 到 3.10? | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu 13.10中升級GNOME 到 3.10? | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu 13.10中升級GNOME 到 3.10? | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu 13.10中升級GNOME 到 3.10? | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/How to Upgrade to GNOME 3.10 in Ubuntu 13.10","title":"如何在Ubuntu 13.10中升級GNOME 到 3.10?","tag":"201401","desc":""},"relativePath":"201401/How to Upgrade to GNOME 3.10 in Ubuntu 13.10.md","filePath":"[post].md"}'),m={name:"201401/How to Upgrade to GNOME 3.10 in Ubuntu 13.10.md"};function g(i,t,b,N,E,G){const p=l("Link");return s(),d("div",null,[t[15]||(t[15]=a(`<h1 id="如何在ubuntu-13-10中升級gnome-到-3-10" tabindex="-1">如何在Ubuntu 13.10中升級GNOME 到 3.10? <a class="header-anchor" href="#如何在ubuntu-13-10中升級gnome-到-3-10" aria-label="Permalink to “如何在Ubuntu 13.10中升級GNOME 到 3.10?”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/09/header-bars.jpg" alt=""></p><p><strong>Ubuntu 13.10 中配備了GNOME 3.8桌面。 儘管它相比Unity是一個可靠穩定以及有特色的替代品，但這個版本還是過時了。</strong></p><p>GNOME桌面的最新版本在2013年9月發佈，隨之而來的是一系列改進的功能、應用程序和可用性的調整。從對高分辨率屏幕的支持到客户端應用窗口上的美化，GNOME 3.10無疑是一個引人注目的升級版本。</p><p>好消息是：假設你正在運行Ubuntu 13.10，擁有不錯的網絡操作和命令列水平，那麼你無需繼續使用一個過時版本的GNOME。</p><h3 id="在ubuntu-13-10-上如何升級到gnome-3-10" tabindex="-1">在Ubuntu 13.10 上如何升級到GNOME 3.10 <a class="header-anchor" href="#在ubuntu-13-10-上如何升級到gnome-3-10" aria-label="Permalink to “在Ubuntu 13.10 上如何升級到GNOME 3.10”">​</a></h3><p>為了那些愛略過前言直奔主題的讀者，我還要重申兩點:</p><p><strong>要使用本方法安裝GNOME 3.10，需運行 Ubuntu 13.10版本。</strong></p><p><strong>GNOME 3.10還未在 Ubuntu 13.10上測試，所以升級風險自負。</strong></p><p>首先，讓我們添加GNOME 3 的PPA到Ubuntu的軟件資源中。這個操作可以使用圖形界面完成，但使用命令更容易一些。</p><p>打開一個新的<em>終端</em>窗口，鍵入下列命令，在需要時輸入你的用户密碼：</p><pre><code>sudo add-apt-repository ppa:gnome3-team/gnome3-next &amp;&amp; sudo apt-get update
</code></pre><p>添加完PPA並更新包列表後，我們就可以繼續，開始安裝GNOME 3.10了。運行下列命令，當彈出提示時再次輸入你的用户密碼：</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install gnome-shell ubuntu-gnome-desktop
</code></pre><p>獲取並安裝所有必要的包和組件會花一點時間，所以請耐心一點。</p><p>在安裝過程中，在終端將會彈出一個提示，要求你選擇一種顯示管理器，默認使用的是“登錄窗口”。</p><p>這個決定完全取決於你；UBuntu的Unity Greeter和<strong>GNOME的顯示管理器</strong>都能讓你很輕鬆地在桌面會話之間切換（如果你想保持在Unity界面或者另一個桌面將很方便），但僅僅只有GDM提供給GNOME特定的功能，譬如鎖屏通知。</p><p>當你確定選擇後，使用上下鍵選擇，然後敲擊‘確認/返回’鍵以確認。安裝便會繼續進行。</p><h3 id="增加額外的功能" tabindex="-1">增加額外的功能 <a class="header-anchor" href="#增加額外的功能" aria-label="Permalink to “增加額外的功能”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/09/gnome-music.jpg" alt=""></p>`,20)),n("p",null,[t[1]||(t[1]=e("GNOME 3.10還有一些不錯的新特性和應用-",-1)),u(p,{href:"http://www.omgubuntu.co.uk/2013/09/gnome-3-10-released-with-new-apps-experimental-wayland-support"},{default:o(()=>[...t[0]||(t[0]=[e("包括GNOME天氣，音樂盒及地圖",-1)])]),_:1}),t[2]||(t[2]=e(" 以及其它各種各樣的改變。因為並不是所有的特性都足夠穩定以致於可以被包含在我們之前添加的GNOME 3 PPA中，所以如果你想使用它們，就需要利用到兩個額外的GNOME PPA。",-1))]),t[16]||(t[16]=a(`<p>現在，你需要意識到很重要的是，在這些倉庫裏的一些包據説有穩定性問題。這些問題大多是小問題，譬如應用程序崩潰和損壞。但還是有潛在的可能，導致像使GNOME完全崩潰這樣的重大問題。</p><p>除開這個警告不説，在終端裏打開一個新的選項卡，輸入下列命令：</p><pre><code>sudo add-apt-repository ppa:gnome3-team/gnome3-staging
sudo add-apt-repository ppa:gnome3-team/gnome3
sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade
</code></pre><p>為了添加一些之前提到的很酷的應用，運行這個命令：</p><pre><code>sudo apt-get install gnome-weather gnome-music gnome-maps cheese gnome-documents
</code></pre><p>這樣之後，就搞定了！</p><p>你可能會想先註銷然後重新登錄（記得選擇“GNOME”會話）以確保改動都已經正確生效了。</p><h3 id="細小的差別" tabindex="-1">細小的差別 <a class="header-anchor" href="#細小的差別" aria-label="Permalink to “細小的差別”">​</a></h3><p>如果你在不卸載Unity的情況下安裝GNOME 3.10，那麼有一些注意事項。</p><p>首先，你會發現<strong>在系統設置裏“Online Accounts”有兩個入口</strong>。其中，有鑰匙圖標的是Unity版的，另一個有插孔符號的是GNOME版的。</p><p>一些應用程序可能會要求你往Unity中添加賬户（Shotwell, Gwibber, Empathy），有一些可能是要求往GNOME中添加(Evolution, Documents, Contacts)。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/04/online-accounts.jpg" alt=""></p><p>“通知”和“搜索”入口是GNOME專有的，它們讓你挑選哪些應用程序和資源能夠顯示通知或出現在活動區。</p><h3 id="卸載gnome-3-10" tabindex="-1">卸載GNOME 3.10 <a class="header-anchor" href="#卸載gnome-3-10" aria-label="Permalink to “卸載GNOME 3.10”">​</a></h3><p>假如你已經嘗試了GNOME 3.10，但不喜歡它。這時該怎麼辦？</p><p>使用一個叫做“PPA Purge”的命令列工具，移除GNOME 3.10 是一個相當簡單的過程。這個工具可以在Ubuntu軟件中心裏找到，是目前為止自動移除或降級從PPA安裝的包的最容易的方法。</p>`,16)),n("ul",null,[n("li",null,[u(p,{href:"apt:ppa-purge"},{default:o(()=>[...t[3]||(t[3]=[e("從Ubuntu軟件中心安裝PPA Purge",-1)])]),_:1})])]),t[17]||(t[17]=n("p",null,"為了使用這個工具，我們需要返回終端然後鍵入下面命令，要留意任何出現在降級過程中的提示。",-1)),t[18]||(t[18]=n("pre",null,[n("code",null,`sudo ppa-purge ppa:gnome3-team/gnome3-next
`)],-1)),t[19]||(t[19]=n("p",null,"如果你也添加了其它可選的PPA，你也需要清除它們：",-1)),t[20]||(t[20]=n("pre",null,[n("code",null,`sudo ppa-purge ppa:gnome3-team/gnome3-staging
sudo ppa-purge ppa:gnome3-team/gnome3
`)],-1)),t[21]||(t[21]=n("p",null,"完成後，你就剩下了原來的 GNOME 3.8 桌面。如果你不再想保留GNOME Shell了，你可以執行下列命令去卸載它：",-1)),t[22]||(t[22]=n("pre",null,[n("code",null,`sudo apt-get remove gnome-shell ubuntu-gnome-desktop
`)],-1)),t[23]||(t[23]=n("p",null,"最後，手動移除任何在降級之後可能殘留的應用程序（譬如，Epiphany and GNOME Documents），然後重啓。",-1)),t[24]||(t[24]=n("hr",null,null,-1)),n("p",null,[t[5]||(t[5]=e("via: ",-1)),u(p,{href:"http://www.omgubuntu.co.uk/2013/12/upgrade-gnome-3-10-ubuntu-13-10"},{default:o(()=>[...t[4]||(t[4]=[e("http://www.omgubuntu.co.uk/2013/12/upgrade-gnome-3-10-ubuntu-13-10",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("譯者：",-1)),u(p,{href:"https://github.com/KayGuoWhu"},{default:o(()=>[...t[6]||(t[6]=[e("KAyGuoWhu",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),u(p,{href:"https://github.com/jasminepeng"},{default:o(()=>[...t[7]||(t[7]=[e("jasminepeng",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=e("本文由 ",-1)),u(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創翻譯，",-1)),u(p,{href:"http://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const U=r(m,[["render",g]]);export{w as __pageData,U as default};
